<template>
	<view class="delivery-page" :class="{'dark-page':screen==='call','login-page':screen==='login'}">
		<MobileHeader v-if="screen!=='login'&&screen!=='workbench'&&screen!=='alert'&&screen!=='call'" :title="pageTitle" @back="goBack" />
		<view v-if="screen==='login'" class="login-screen">
			<view class="login-brand"><view class="drop-logo"><view class="drop-wave"></view></view><text class="ui-strong">山泉配送</text><text>专业 · 高效 · 便捷</text></view>
			<view class="login-form"><text class="integration-note">当前为本地联调身份登录，生产环境需接入真实微信或账号认证</text><view><AppIcon name="phone" size="30rpx" tone="muted"/><input v-model="phone" type="number" maxlength="11" placeholder="请输入已绑定手机号" /></view><button @click="login">登录工作台</button></view>
			<view class="current-station"><text>当前水站</text><view><AppIcon name="pin" size="29rpx"/><text class="ui-strong">{{courierProfile.station || '中央站'}}</text><text>›</text></view></view>
		</view>

		<template v-else-if="screen==='workbench'||screen==='alert'">
			<view class="work-hero"><view class="work-profile"><view class="avatar">{{(courierProfile.name || '送').slice(0,1)}}</view><view><text class="ui-strong">{{courierProfile.name || '送水员'}}</text><text>{{courierProfile.station || '中央站'}}</text></view><view class="online"><text>{{online ? '接单中' : '已暂停提醒'}}</text><switch :checked="online" color="#68d8bf" @change="toggleOnline"/></view></view></view>
			<scroll-view scroll-y class="work-scroll">
				<view class="stats-card"><view class="today"><text>今日配送</text><text class="ui-strong">{{deliveryStats.total}}<text class="ui-small"> 单</text></text></view><view class="stat-grid"><view><text class="ui-strong">{{deliveryStats.pending}}</text><text>待配送</text></view><view><text class="ui-strong">{{deliveryStats.delivering}}</text><text>配送中</text></view><view><text class="ui-strong">{{deliveryStats.completed}}</text><text>已完成</text></view></view><view class="bar-stat"><text>配送桶数</text><text class="ui-strong">{{deliveryStats.barrels}}<text class="ui-small"> 桶</text></text></view></view>
				<view class="section-row"><text class="ui-strong">下一单任务</text><text @click="loadOrders(true)">刷新</text></view>
				<view v-if="nextOrder" class="next-card" @click="selectOrder(nextOrder)"><view><text class="ui-strong">{{nextOrder.customer}}</text><text class="status-chip">{{nextOrder.status}}</text></view><text>{{nextOrder.address}}</text><text class="ui-strong">{{nextOrder.deliveryWindow || nextOrder.timeLabel}} <text class="ui-small">{{nextOrder.deliveryWindow ? '配送时段' : '下单'}}</text></text><view><text>{{nextOrder.spec}} · {{nextOrder.courierId ? '已由后台派单' : '等待派单'}}</text><text>›</text></view></view>
				<view v-else class="next-card"><view><text class="ui-strong">暂无配送任务</text><text class="status-chip">已同步</text></view><text>后台派单后会自动出现在这里</text></view>
				<view class="section-row"><text class="ui-strong">常用工具</text></view><view class="tools"><view @click="openTicketSign"><view class="tool-icon"><AppIcon name="ticket" size="31rpx" tone="light"/></view><text>水票核销</text></view><view @click="open('sign')"><view class="tool-icon"><AppIcon name="check" size="31rpx" tone="light"/></view><text>主动签收</text></view><view class="unavailable" @click="toast('来电识别需要运营商线路与 SDK，当前为外部条件阻塞')"><view class="tool-icon"><AppIcon name="phone" size="31rpx" tone="light"/></view><text>来电识别·未接入</text></view><view class="unavailable" @click="toast('配送地图需要地图 SDK 与订单坐标，当前为外部条件阻塞')"><view class="tool-icon"><AppIcon name="map" size="31rpx" tone="light"/></view><text>配送地图·未接入</text></view></view>
				<view class="section-row"><text class="ui-strong">今日订单</text><text @click="navChange('orders')">全部订单 ›</text></view><view class="simple-order" v-for="o in orders.slice(0,6)" :key="o.id" @click="selectOrder(o)"><view class="order-index">{{o.index}}</view><view><text class="ui-strong">{{o.customer}}</text><text>{{o.address}}</text></view><view><text class="ui-strong">{{o.timeLabel}}</text><text>{{o.status}}</text></view></view>
				<view v-if="!orders.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">今日暂无订单</text><text>后台派单后会实时出现</text></view></view>
			</scroll-view>
			<BottomNav active="workbench" variant="delivery" :badge="activeOrderCount" @change="navChange"/>
			<view v-if="screen==='alert'" class="alert-layer"><view class="alert-card"><view class="bell"><AppIcon name="bell" size="50rpx" tone="light"/></view><text class="ui-strong">新订单已派送给您</text><text>请及时处理</text><view class="alert-info"><view><text>客户</text><text class="ui-strong">{{pendingOrder?.customer || '同步中'}}</text><AppIcon name="phone" size="26rpx"/></view><view><text>地址</text><text class="ui-strong">{{pendingOrder?.address || '同步中'}}</text></view><view><text>商品</text><text class="ui-strong">{{pendingOrder?.spec || '同步中'}}</text></view><view><text>订单号</text><text class="ui-strong">{{pendingOrder?.id || '同步中'}}</text><AppIcon name="pin" size="25rpx"/></view></view><button @click="acceptOrder">立即接单</button><text class="later" @click="open('workbench')">稍后处理（{{countdown}}s）</text></view></view>
		</template>

		<template v-else-if="screen==='orders'||screen==='messages'||screen==='mine'">
			<view class="work-hero compact"><view class="work-profile"><view class="avatar">{{(courierProfile.name || '送').slice(0,1)}}</view><view><text class="ui-strong">{{ {orders:'我的订单',messages:'消息动态',mine:'我的'}[screen] }}</text><text>{{courierProfile.name || '送水员'}} · {{courierProfile.station || '中央站'}}</text></view></view></view>
			<scroll-view scroll-y class="work-scroll">
				<template v-if="screen==='orders'">
					<view class="segment-row"><text v-for="tab in orderTabs" :key="tab" :class="{active:orderTab===tab}" @click="orderTab=tab">{{tab}}</text></view>
					<view class="simple-order" v-for="o in filteredOrders" :key="o.id" @click="selectOrder(o)"><view class="order-index">{{o.index}}</view><view><text class="ui-strong">{{o.customer}} · {{o.spec}}</text><text>{{o.address}}</text></view><view><text class="ui-strong">{{o.deliveryWindow || o.timeLabel}}</text><text>{{o.status}}</text></view></view>
					<view v-if="!filteredOrders.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">暂无{{orderTab==='全部'?'':orderTab}}订单</text><text>数据每 3 秒自动同步</text></view></view>
				</template>
				<template v-else-if="screen==='messages'">
					<view class="simple-order" v-for="m in messages" :key="m.key"><view class="order-index"><AppIcon name="bell" size="26rpx" tone="light"/></view><view><text class="ui-strong">{{m.title}}</text><text>{{m.orderId}} · {{m.customer}}</text></view><view><text class="ui-strong">{{m.time}}</text><text>{{m.status}}</text></view></view>
					<view v-if="!messages.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">暂无消息</text><text>派单、接单、签收都会记录在这里</text></view></view>
				</template>
				<template v-else>
					<view class="stats-card"><view class="today"><text>今日完成</text><text class="ui-strong">{{deliveryStats.completed}}<text class="ui-small"> 单</text></text></view><view class="stat-grid"><view><text class="ui-strong">{{deliveryStats.pending}}</text><text>待配送</text></view><view><text class="ui-strong">{{deliveryStats.delivering}}</text><text>配送中</text></view><view><text class="ui-strong">{{deliveryStats.barrels}}</text><text>桶数</text></view></view></view>
					<view class="mine-list"><view><text>姓名</text><text class="ui-strong">{{courierProfile.name || '送水员'}}</text></view><view><text>手机号</text><text class="ui-strong">{{courierProfile.phone || phone || '--'}}</text></view><view><text>所属水站</text><text class="ui-strong">{{courierProfile.station || '中央站'}}</text></view><view><text>接单提醒</text><text class="ui-strong">{{online ? '开启' : '已暂停'}}</text></view></view>
					<button class="logout-button" @click="logout">退出登录</button>
				</template>
			</scroll-view>
			<BottomNav :active="screen" variant="delivery" :badge="activeOrderCount" @change="navChange"/>
		</template>

		<scroll-view v-else-if="screen==='delivery-detail'" scroll-y class="detail-scroll">
			<view class="delivery-state"><view class="clock"><AppIcon name="clock" size="35rpx" tone="light"/></view><view><text class="ui-strong">{{activeOrder?.status || '配送中'}}</text><text>{{activeOrder?.dispatchStatus || '订单状态实时同步'}}</text></view></view>
			<view class="detail-card customer"><view><text>客户</text><text class="ui-strong">{{activeOrder?.customer || '暂无客户'}}</text><text>{{activeOrder?.phone || '--'}}</text></view><button @click="callCustomer"><AppIcon name="phone" size="32rpx"/></button></view>
			<view class="detail-card address-block"><view><text>地址</text><text class="ui-strong">{{activeOrder?.address || '暂无地址'}}</text></view><button class="unavailable" @click="toast('订单尚无可用经纬度')"><AppIcon name="pin" size="30rpx"/><text class="ui-small">未接入</text></button></view>
			<view class="detail-card"><text class="block-title">商品</text><view class="product-line"><WaterJug size="small"/><view><text class="ui-strong">{{activeOrder?.spec || '18.9L桶装水 × 1'}}</text><text>¥{{Number(activeOrder?.amount || 15).toFixed(2)}}</text></view></view><view class="recycle"><text class="ui-span">空桶回收</text><text class="ui-strong">回收空桶 × {{activeOrder?.quantity || 1}}</text></view></view>
			<view class="detail-card note"><text>备注</text><text class="ui-strong">{{activeOrder?.remark || '无特殊备注'}}</text></view>
		</scroll-view>

		<scroll-view v-else-if="screen==='sign'" scroll-y class="detail-scroll sign-scroll">
			<text class="sign-label">选择签收方式</text><view class="sign-options"><view v-for="item in signOptions" :key="item.id" :class="{active:signMethod===item.id,unavailable:!item.available}" @click="item.available&&(signMethod=item.id)"><view class="sign-icon"><AppIcon :name="item.icon" size="30rpx"/></view><view><text class="ui-strong">{{item.name}}</text><text class="ui-small">{{item.note}}</text></view><text class="ui-span">{{signMethod===item.id?'✓':''}}</text></view></view>
			<view v-if="signMethod==='ticket'" class="ticket-form"><text class="sign-label">核销客户水票</text><view class="segment-row"><text :class="{active:ticketType==='纸质票'}" @click="ticketType='纸质票'">纸质票</text><text :class="{active:ticketType==='电子票'}" @click="ticketType='电子票'">电子票</text></view><view class="ticket-input"><input v-model="ticketCode" placeholder="输入水票编码，如 JT000238 / ET0001" /><button @click="scanTicketCode"><AppIcon name="qr" size="26rpx" tone="light"/></button></view><text class="ui-small">签收时会校验该票属于当前客户并立即核销，不能重复使用</text></view>
			<text class="sign-label">送达凭证（可选，上传后随订单保存并同步给客户）</text><view class="proof-photo"><image v-if="proofLocalPath" :src="proofLocalPath" mode="aspectFill"/><WaterJug v-else size="medium"/><view class="retake" @click="chooseProof"><AppIcon name="camera" size="24rpx" tone="light"/><text>{{proofLocalPath?'重新拍照':'选择照片'}}</text></view></view><view class="confirm-check" @click="confirmed=!confirmed"><text class="ui-span" :class="{on:confirmed}">{{confirmed?'✓':''}}</text><text>已与客户沟通并完成送达</text></view>
		</scroll-view>

		<view v-else class="call-screen"><view class="status-only light"><text>电话接入演示</text><text>尚未连接运营商</text></view><text class="calling">来电信息仅为视觉稿</text><text class="ui-strong caller">未接入</text><text class="caller-phone">需要真实电话线路与 SDK</text><view class="caller-tags"><text>外部条件阻塞</text></view><view class="customer-preview"><view><text>当前状态</text><text class="ui-strong">不可用于生产</text></view><view><text>所需配置</text><text>运营商账号、回调域名、SDK</text></view></view><view class="call-actions"><view><button class="hangup" @click="open('workbench')"><AppIcon name="phone" size="43rpx" tone="light"/></button><text>返回</text></view><view><button class="answer unavailable" @click="answerCall"><AppIcon name="phone" size="43rpx" tone="light"/></button><text>未接入</text></view></view></view>

		<view v-if="screen==='delivery-detail'" class="double-action"><button class="ghost" @click="callCustomer">☎ 联系客户</button><button @click="open('sign')">确认送达</button></view>
		<view v-else-if="screen==='sign'" class="single-action"><button :disabled="signing" @click="finishSign">{{ signing ? '正在签收…' : (signMethod==='ticket' ? '核销水票并签收' : '确认签收') }}</button></view>
	</view>
</template>

<script>
import MobileHeader from '../../components/MobileHeader.vue'
import BottomNav from '../../components/BottomNav.vue'
import WaterJug from '../../components/WaterJug.vue'
import AppIcon from '../../components/AppIcon.vue'
import { waterApi } from '../../services/waterApi.js'

export default {
	components:{MobileHeader,BottomNav,WaterJug,AppIcon},
	data(){return{screen:'login',phone:'',countdown:15,countdownTimer:null,signMethod:'manual',confirmed:true,proofLocalPath:'',signing:false,ticketType:'纸质票',ticketCode:'',online:true,orderTab:'全部',orderTabs:['全部','待配送','配送中','已完成'],refreshTimer:null,selectedOrder:null,knownPendingIds:[],courierProfile:{name:'送水员',station:'中央站',phone:''},
		orders:[],
		signOptions:[{id:'manual',icon:'camera',name:'送水员主动签收',note:'由送水员手动确认送达',available:true},{id:'ticket',icon:'ticket',name:'核销水票签收',note:'输入客户纸质票/电子票编码，签收时核销',available:true},{id:'scan',icon:'qr',name:'客户扫码签收',note:'需客户端出示签收二维码，暂未开放',available:false}]
	}},
	computed:{pageTitle(){return{'delivery-detail':'配送单详情',sign:this.signMethod==='ticket'?'水票核销签收':'主动签收'}[this.screen]||''},pendingOrder(){return this.orders.find(order=>order.status==='待配送')},nextOrder(){return this.orders.find(order=>order.status==='配送中')||this.pendingOrder||this.orders[0]},activeOrder(){return this.selectedOrder||this.nextOrder},activeOrderCount(){return this.orders.filter(order=>['待配送','配送中'].includes(order.status)).length},filteredOrders(){return this.orderTab==='全部'?this.orders:this.orders.filter(order=>order.status===this.orderTab)},deliveryStats(){return{total:this.orders.length,pending:this.orders.filter(order=>order.status==='待配送').length,delivering:this.orders.filter(order=>order.status==='配送中').length,completed:this.orders.filter(order=>order.status==='已完成').length,barrels:this.orders.reduce((sum,order)=>sum+Number(order.quantity||1),0)}},
		messages(){const labels={seed:'历史订单',create:'客户下单',pay:'客户已支付','pay-balance':'客户余额支付',assign:'后台派单给你',accept:'你已接单',complete:'签收完成',cancel:'订单已取消','auto-cancel':'超时未支付关闭'};const list=[];for(const order of this.orders){for(const event of order.timeline||[]){list.push({key:`${order.id}-${event.at}-${event.action}`,orderId:order.id,customer:order.customer,title:labels[event.action]||event.action,status:event.status,at:event.at,time:this.formatTime(event.at)})}}return list.sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,30)}},
	watch:{screen(value){if(value==='alert')this.startCountdown();else this.stopCountdown()}},
	onLoad(query){if(query&&query.screen)this.screen=query.screen;try{const saved=uni.getStorageSync('water_courier_online');if(saved==='off')this.online=false}catch(error){console.warn('[courier-pref]',error)}if(this.screen!=='login')this.startSync();if(this.screen==='alert')this.startCountdown()},
	onShow(){if(this.screen!=='login')this.startSync()},
	onUnload(){this.stopSync();this.stopCountdown()},
	methods:{
		open(name){this.screen=name;uni.pageScrollTo({scrollTop:0,duration:0});if(name==='login')this.stopSync();else this.startSync()},goBack(){this.open(this.screen==='sign'?'delivery-detail':'workbench')},
		toast(title){uni.showToast({title,icon:'none'})},formatTime(value){const date=new Date(value);return Number.isNaN(date.getTime())?'--:--':`${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')} ${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`},
		async login(){if(!/^1\d{10}$/.test(this.phone))return this.toast('请输入 11 位已绑定手机号');try{const session=await waterApi.login('courier',{phone:this.phone},true);this.courierProfile=session.profile||this.courierProfile;await this.loadOrders();this.open(this.pendingOrder&&this.online?'alert':'workbench')}catch(error){this.toast(error.message)}},
		logout(){uni.showModal({title:'退出登录',content:'退出后将停止接收派单提醒',success:result=>{if(!result.confirm)return;waterApi.logout('courier');this.orders=[];this.selectedOrder=null;this.knownPendingIds=[];this.open('login')}})},
		toggleOnline(event){this.online=Boolean(event?.detail?.value);try{uni.setStorageSync('water_courier_online',this.online?'on':'off')}catch(error){console.warn('[courier-pref]',error)}this.toast(this.online?'已开启新单提醒':'已暂停新单提醒，仍可手动接单')},
		startCountdown(){this.stopCountdown();this.countdown=15;this.countdownTimer=setInterval(()=>{this.countdown-=1;if(this.countdown<=0){this.stopCountdown();if(this.screen==='alert')this.screen='workbench'}},1000)},stopCountdown(){if(this.countdownTimer){clearInterval(this.countdownTimer);this.countdownTimer=null}},
		mapOrder(order,index){return{...order,index:index+1,timeLabel:this.formatTime(order.createdAt)}},
		async loadOrders(notify=false){try{const data=await waterApi.listCourierOrders();this.courierProfile=waterApi.getProfile('courier')||this.courierProfile;const mapped=data.map((order,index)=>this.mapOrder(order,index));const pendingIds=mapped.filter(order=>order.status==='待配送').map(order=>order.id);const hasNew=pendingIds.some(id=>!this.knownPendingIds.includes(id));this.orders=mapped;if(this.selectedOrder){const latest=mapped.find(order=>order.id===this.selectedOrder.id);if(latest)this.selectedOrder=latest}if(hasNew&&this.online&&this.knownPendingIds.length&&this.screen==='workbench')this.screen='alert';this.knownPendingIds=pendingIds;if(notify)this.toast('订单已同步')}catch(error){console.warn('[delivery-sync]',error.message)}},
		startSync(){this.stopSync();this.loadOrders();this.refreshTimer=setInterval(()=>this.loadOrders(),3000)},stopSync(){if(this.refreshTimer){clearInterval(this.refreshTimer);this.refreshTimer=null}},selectOrder(order){this.selectedOrder=order;this.open('delivery-detail')},
		async acceptOrder(){const order=this.pendingOrder;if(!order)return this.toast('暂无待接订单');try{const updated=await waterApi.acceptOrder(order.id);this.selectedOrder=this.mapOrder(updated,0);this.toast('接单成功，用户端已同步');await this.loadOrders();this.open('delivery-detail')}catch(error){this.toast(error.message)}},answerCall(){this.toast('电话系统尚未接入')},
		openTicketSign(){const order=this.orders.find(item=>item.status==='配送中')||this.activeOrder;if(!order)return this.toast('暂无配送中的订单可核销');this.selectedOrder=order;this.signMethod='ticket';this.open('sign')},
		scanTicketCode(){if(typeof uni.scanCode!=='function')return this.toast('当前环境不支持扫码，请手动输入');uni.scanCode({scanType:['qrCode','barCode'],success:result=>{this.ticketCode=String(result.result||'').trim()},fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('扫码失败，请手动输入')}})},
		callCustomer(){const phone=String(this.activeOrder?.phone||'').replace(/\D/g,'');if(phone.length!==11||typeof uni.makePhoneCall!=='function')return this.toast('订单没有可直接拨打的完整手机号');uni.makePhoneCall({phoneNumber:phone,fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('拨号失败')}})},
		chooseProof(){if(typeof uni.chooseImage!=='function')return this.toast('当前环境不支持选择照片');uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['camera','album'],success:result=>{this.proofLocalPath=result.tempFilePaths?.[0]||''},fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('照片选择失败')}})},
		async finishSign(){if(this.signing)return;if(!this.confirmed)return this.toast('请确认已完成送达');if(!this.activeOrder)return this.toast('暂无可签收订单');if(this.signMethod==='ticket'&&!this.ticketCode.trim())return this.toast('请输入或扫描水票编码');this.signing=true;try{let order=this.activeOrder;if(order.status==='待配送')order=await waterApi.acceptOrder(order.id);if(order.status!=='配送中')return this.toast('仅配送中订单可签收');let proofUrl='';if(this.proofLocalPath){const uploaded=await waterApi.uploadImage(this.proofLocalPath,'courier');proofUrl=uploaded.url}const payload={signMethod:this.signMethod,proofUrl:proofUrl||undefined};if(this.signMethod==='ticket'){payload.ticketType=this.ticketType;payload.ticketCode=this.ticketCode.trim().toUpperCase()}const updated=await waterApi.completeOrder(order.id,payload);this.selectedOrder=this.mapOrder(updated,0);this.proofLocalPath='';this.ticketCode='';this.toast(this.signMethod==='ticket'?'水票已核销，签收完成':'签收完成，三端状态已同步');this.signMethod='manual';await this.loadOrders();setTimeout(()=>this.open('workbench'),600)}catch(error){this.toast(error.message)}finally{this.signing=false}},
		navChange(name){if(['workbench','orders','messages','mine'].includes(name))this.open(name)},
	}
}
